// GENERATED BY AI
//
// Small deterministic cache workload for the ImGui cache visualizer.
#include "test_cases.h"
#include <cstdio>
#include <vector>
#include "../defines.h"

namespace Test {
namespace {

// addr = [tag | index(2) | offset(4)]
constexpr u32 make_addr(u32 tag, u32 set, u32 offset) {
    return (tag << 6) | (set << 4) | offset;
}

struct Case {
    const char* desc;
    u32 addr;
    bool write;
    u32 wrdata;
};

const Case kCases[] = {
    {"Cold miss: read set 0, tag 0",           make_addr(0, 0, 0x0), false, 0},
    {"Hit: read set 0, word 1",                make_addr(0, 0, 0x4), false, 0},
    {"Cold miss: read set 1, tag 0",           make_addr(0, 1, 0x0), false, 0},
    {"Write hit: set 1, word 1 (sets dirty)",  make_addr(0, 1, 0x4), true,  0xDEADBEEF},
    {"Miss: set 0, tag 1 -> fills way 1",      make_addr(1, 0, 0x0), false, 0},
    {"Write hit: set 0, tag 0 (way 0 dirty)",  make_addr(0, 0, 0x0), true,  0xCAFEF00D},
    {"Miss: set 0, tag 2 -> evicts LRU (tag 1, clean)",
                                               make_addr(2, 0, 0x8), false, 0},
    {"Hit: set 0, tag 2, word 3",              make_addr(2, 0, 0xC), false, 0},
    {"Cold miss: set 3, tag 0",                make_addr(0, 3, 0x0), false, 0},
    {"Miss: set 0, tag 1 -> evicts DIRTY tag 0 (writeback)",
                                               make_addr(1, 0, 0x0), false, 0},
    {"Write miss: set 2, tag 5 (write-allocate)",
                                               make_addr(5, 2, 0x4), true,  0x12345678},
};

// LRU bookkeeping, per set/way.
std::vector<std::vector<u64>> g_last_use;
u64 g_clock = 0;

// Fake backing memory: deterministic value per word address.
u32 backing_word(u32 word_addr) {
    return 0xA0000000u ^ (word_addr * 0x01010101u);
}

int pick_victim(const CacheSnapshot& c, int set) {
    for (int w = 0; w < c.ways_; ++w)
        if (!c.at(set, w).valid_) return w;

    int victim = 0;
    for (int w = 1; w < c.ways_; ++w)
        if (g_last_use[set][w] < g_last_use[set][victim]) victim = w;
    return victim;
}

} // namespace

void test_cache_impl(CacheSnapshot& c) {
    c.sets_ = 4;
    c.ways_ = 2;
    c.line_bytes_ = 16;
    c.words_per_line_ = 4;
    c.index_bits_ = 2;
    c.offset_bits_ = 4;

    CacheLine empty;
    empty.words_.assign(c.words_per_line_, 0);
    c.cache_.assign(c.sets_, std::vector<CacheLine>(c.ways_, empty));

    g_last_use.assign(c.sets_, std::vector<u64>(c.ways_, 0));
    g_clock = 0;
}

int test_case_count() {
    return static_cast<int>(sizeof(kCases) / sizeof(kCases[0]));
}

void run_test_case(int idx, CacheSnapshot& c, CacheRequest& req,
                   CacheLookupResult& result, std::string* description) {
    const Case& tc = kCases[idx];

    req = {};
    req.addr_   = tc.addr;
    req.rd_     = !tc.write;
    req.wr_     = tc.write;
    req.wrdata_ = tc.wrdata;

    result = c.lookup(req.addr_);

    int way;
    std::string note;

    if (result.hit_) {
        way = result.way_;
        note = "HIT";
    } else {
        way = pick_victim(c, result.set_);
        result.victim_way_ = way;

        CacheLine& line = c.at(result.set_, way);
        if (line.valid_ && line.dirty_)
            note = "MISS (writeback dirty line, tag " + std::to_string(line.tag_) + ")";
        else if (line.valid_)
            note = "MISS (evict clean line, tag " + std::to_string(line.tag_) + ")";
        else
            note = "MISS (fill empty way)";

        // Refill the whole line from backing memory.
        const u32 line_base = req.addr_ & ~(u32(c.line_bytes_) - 1);
        line.valid_ = true;
        line.dirty_ = false;
        line.tag_   = result.tag_;
        line.words_.resize(c.words_per_line_);
        for (int i = 0; i < c.words_per_line_; ++i)
            line.words_[i] = backing_word((line_base >> 2) + i);
    }

    CacheLine& line = c.at(result.set_, way);
	result.evicted_   = line.valid_;
	result.writeback_ = line.valid_ && line.dirty_;
    if (req.wr_) {
        line.words_[result.word_index_] = req.wrdata_;
        line.dirty_ = true;
    }

    g_last_use[result.set_][way] = ++g_clock;

    if (description) {
        char buf[64];
        std::snprintf(buf, sizeof(buf), " [addr 0x%08X, set %d, way %d]",
                      req.addr_, result.set_, way);
        *description = std::string(tc.desc) + " -> " + note + buf;
    }
}

} // namespace Test
